1	import deepEqual from '../utils/deepEqual';
2	import isNullOrUndefined from '../utils/isNullOrUndefined';
3	import isObject from '../utils/isObject';
4	import isPrimitive from '../utils/isPrimitive';
5	import isUndefined from '../utils/isUndefined';
6	import objectHasFunction from '../utils/objectHasFunction';
7	
8	function isTraversable<T>(value: T): boolean {
9	  return Array.isArray(value) || (isObject(value) && !objectHasFunction(value));
10	}
11	
12	function markFieldsDirty<T>(data: T, fields: Record<string, any> = {}) {
13	  for (const key in data) {
14	    const value = data[key];
15	
16	    if (isTraversable(value)) {
17	      fields[key] = Array.isArray(value) ? [] : {};
18	      markFieldsDirty(value, fields[key]);
19	    } else if (!isUndefined(value)) {
20	      fields[key] = true;
21	    }
22	  }
23	
24	  return fields;
25	}
26	
27	function pruneDirtyFields<T>(value: T): T {
28	  if (value === false) {
29	    return undefined as T;
30	  }
31	
32	  if (value === true) {
33	    return true as T;
34	  }
35	
36	  if (Array.isArray(value)) {
37	    const result = value.map((value) => pruneDirtyFields(value));
38	    return (
39	      result.some((value) => value !== undefined) ? result : undefined
40	    ) as T;
41	  }
42	
43	  if (isObject(value)) {
44	    const result: Record<string, unknown> = {};
45	
46	    for (const key in value) {
47	      const pruned = pruneDirtyFields(value[key]);
48	
49	      if (!isUndefined(pruned)) {
50	        result[key] = pruned;
51	      }
52	    }
53	
54	    return (Object.keys(result).length ? result : undefined) as T;
55	  }
56	
57	  return undefined as T;
58	}
