60	export default function getDirtyFields<T>(
61	  data: T,
62	  formValues: T,
63	  dirtyFieldsFromValues?: Record<
64	    Extract<keyof T, string>,
65	    ReturnType<typeof markFieldsDirty> | boolean
66	  >,
67	) {
68	  if (!dirtyFieldsFromValues) {
69	    dirtyFieldsFromValues = markFieldsDirty(formValues);
70	  }
71	
72	  for (const key in data) {
73	    const value = data[key];
74	
75	    if (isTraversable(value)) {
76	      if (isUndefined(formValues) || isPrimitive(dirtyFieldsFromValues[key])) {
77	        dirtyFieldsFromValues[key] = markFieldsDirty(
78	          value,
79	          Array.isArray(value) ? [] : {},
80	        );
81	      } else {
82	        getDirtyFields(
83	          value,
84	          isNullOrUndefined(formValues) ? {} : formValues[key],
85	          dirtyFieldsFromValues[key],
86	        );
87	      }
88	    } else {
89	      const formValue = formValues[key];
90	      dirtyFieldsFromValues[key] = !deepEqual(value, formValue);
91	    }
92	  }
93	
94	  return pruneDirtyFields(dirtyFieldsFromValues) || {};
95	}
