      data: { id: number; name: string }[];
    };

    const defaultValues: IData = {
      data: [{ id: 1, name: 'a' }],
    };

    const { result } = renderHook(() =>
      useForm<IData>({
        defaultValues,
      }),
    );

    result.current.register('data.0.name');
    result.current.formState.isDirty;
